guN(){return"\u0cac\u0ccd\u0caf\u0cbe\u0c95\u0ccd \u0c86\u0cab\u0cc0\u0cb8\u0ccd, \u0cab\u0ccd\u0cb0\u0cbe\u0c82\u0c9a\u0cc8\u0cb8\u0ccd \u0cae\u0cc1\u0c96\u0ccd\u0caf\u0cb8\u0ccd\u0ca5\u0cb0\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc1 \u0c86\u0ca1\u0ccd\u0cae\u0cbf\u0ca8\u0ccd \u0cae\u0cbe\u0ca4\u0ccd\u0cb0. \u0cae\u0cbe\u0cb0\u0cbe\u0c9f\u0c97\u0cbe\u0cb0\u0cb0\u0cc1, \u0c97\u0ccd\u0cb0\u0cbe\u0cb9\u0c95\u0cb0\u0cc1, \u0cb6\u0cbf\u0cab\u0cbe\u0cb0\u0cb8\u0cc1 \u0caa\u0cbe\u0cb2\u0cc1\u0ca6\u0cbe\u0cb0\u0cb0\u0cc1 \u0c8e\u0c82\u0ca6\u0cc2 \u0ca8\u0ccb\u0ca1\u0cc1\u0cb5\u0cc1\u0ca6\u0cbf\u0cb2\u0ccd\u0cb2."},
guO(){return"\u0c86\u0c82\u0ca4\u0cb0\u0cbf\u0c95 \u0c9f\u0cbf\u0caa\u0ccd\u0caa\u0ca3\u0cbf\u0c97\u0cb3\u0ca8\u0ccd\u0ca8\u0cc1 \u0caf\u0cbe\u0cb0\u0cc1 \u0ca8\u0ccb\u0ca1\u0cac\u0cb9\u0cc1\u0ca6\u0cc1?"},
guP(){return"O2O Boss \u0ca8\u0cbf\u0c97\u0ca6\u0cbf\u0caa\u0ca1\u0cbf\u0cb8\u0cbf\u0ca6 \u0cb9\u0c82\u0ca4\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf \u0c95\u0cae\u0cbf\u0cb7\u0ca8\u0ccd \u0c86\u0c97\u0cc1\u0ca4\u0ccd\u0ca4\u0ca6\u0cc6, \u0cb8\u0cbe\u0cae\u0cbe\u0ca8\u0ccd\u0caf\u0cb5\u0cbe\u0c97\u0cbf \u0c97\u0ccd\u0cb0\u0cbe\u0cb9\u0c95\u0cb0\u0cc1 \u0caa\u0cc2\u0cb0\u0ccd\u0ca4\u0cbf \u0caa\u0cbe\u0cb5\u0ca4\u0cbf\u0cb8\u0cbf\u0ca6\u0cbe\u0c97. \u0c97\u0cb3\u0cbf\u0c95\u0cc6 \u0cb5\u0cbf\u0cad\u0cbe\u0c97\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf \u0ca8\u0ccb\u0ca1\u0cac\u0cb9\u0cc1\u0ca6\u0cc1."},
guQ(){return"\u0ca8\u0ca8\u0ccd\u0ca8 \u0c95\u0cae\u0cbf\u0cb7\u0ca8\u0ccd \u0caf\u0cbe\u0cb5\u0cbe\u0c97 \u0cb8\u0cbf\u0c97\u0cc1\u0ca4\u0ccd\u0ca4\u0ca6\u0cc6?"},
