guZ(){return"\u0c15\u0c38\u0c4d\u0c1f\u0c2e\u0c30\u0c4d\u200c\u0c15\u0c41 \u0c35\u0c46\u0c33\u0c4d\u0c32\u0c47 \u0c2e\u0c41\u0c02\u0c26\u0c41 \u0c2c\u0c4d\u0c2f\u0c3e\u0c15\u0c4d \u0c06\u0c2b\u0c40\u0c38\u0c4d \u0c24\u0c28\u0c3f\u0c16\u0c40 \u0c1a\u0c47\u0c38\u0c4d\u0c24\u0c41\u0c02\u0c26\u0c3f. O2O Boss \u0c2a\u0c4d\u0c30\u0c24\u0c3f \u0c15\u0c4a\u0c1f\u0c47\u0c37\u0c28\u0c4d \u0c15\u0c3e\u0c2a\u0c40\u0c28\u0c3f \u0c09\u0c02\u0c1a\u0c41\u0c15\u0c41\u0c02\u0c1f\u0c41\u0c02\u0c26\u0c3f."},
gv_(){return"\u0c28\u0c3e \u0c15\u0c4a\u0c1f\u0c47\u0c37\u0c28\u0c4d\u200c\u0c28\u0c41 \u0c0e\u0c35\u0c30\u0c41 \u0c24\u0c28\u0c3f\u0c16\u0c40 \u0c1a\u0c47\u0c38\u0c4d\u0c24\u0c3e\u0c30\u0c41?"},
